303	fn diagnostic_json(
304	  value : Json,
305	  environment : Map[String, String],
306	  protected_secrets : Array[String],
307	  truncated : Ref[Bool],
308	  depth : Int32,
309	  stable_activity~ : Bool = false,
310	  secret_states~ : Bool = false,
311	  stable_operation~ : Bool = false,
312	) -> Json {
313	  if depth >= 64 {
314	    truncated.val = true
315	    return Json::string("[nested evidence omitted]")
316	  }
317	  match value {
318	    Json::Object(values) => {
319	      let result = Json::empty_object()
320	      for name, item in values {
321	        let key = name.to_lower().replace_all(old="_", new="")
322	        let safe_name = if (
323	            stable_operation &&
324	            depth == 0 &&
325	            ["operationId", "workspaceId"].contains(name)
326	          ) ||
327	          (
328	            stable_activity &&
329	            [
330	              "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
331	              "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
332	              "workspaceId", "source", "code", "id", "uid", "context", "provider",
333	              "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
334	              "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
335	              "error", "autoStop",
336	            ].contains(name)
337	          ) {
338	          name
339	        } else {
340	          diagnostic_text(name, environment~, protected_secrets~)
341	        }
342	        if field(result, safe_name) is Some(_) {
343	          truncated.val = true
344	          continue
345	        }
346	        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
347	          truncated.val = true
348	        }
349	        set_field(
350	          result,
351	          safe_name,
352	          if credential_field(name) || key == "pairingcode" {
353	            if secret_states &&
354	              field(item, "state") is Some(Json::String(state)) &&
355	              ["unset", "empty", "set"].contains(state) {
356	              let masked : Json = { "state": state }
357	              if field(item, "value") is Some(_) {
358	                set_field(masked, "value", Json::string("[redacted]"))
359	              }
360	              if field(item, "truncated") == Some(Json::boolean(true)) {
361	                set_field(masked, "truncated", Json::boolean(true))
362	                truncated.val = true
363	              }
364	              masked
365	            } else {
366	              Json::string("[redacted]")
367	            }
368	          } else if stable_activity &&
369	            name == "activity" &&
370	            (
371	              item == Json::string("idle") ||
372	              item == Json::string("active") ||
373	              item == Json::string("unknown")
374	            ) {
375	            item
376	          } else {
377	            diagnostic_json(
378	              item,
379	              environment,
380	              protected_secrets,
381	              truncated,
382	              depth + 1,
383	              stable_activity~,
384	              secret_states~,
385	              stable_operation~,
386	            )
387	          },
388	        )
389	      }
390	      result
391	    }
392	    Json::Array(values) =>
393	      Json::array(
394	        values.map(item => {
395	          diagnostic_json(
396	            item,
397	            environment,
398	            protected_secrets,
399	            truncated,
400	            depth + 1,
401	            stable_activity~,
402	            secret_states~,
403	            stable_operation~,
404	          )
405	        }),
406	      )
407	    Json::String(text) => {
408	      let safe = diagnostic_text(text, environment~, protected_secrets~)
409	      if safe.has_suffix("\n[error details incomplete or truncated]") {
410	        truncated.val = true
411	      }
412	      Json::string(safe)
413	    }
414	    _ => value
415	  }
416	}
