260	async fn recover_diagnostic_health(directory : String) -> Unit {
261	  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
262	    return
263	  }
264	  let path = directory + "/diagnostic-health.json"
265	  if !@fs.exists(path) {
266	    return
267	  }
268	  let previous = @async.with_timeout(20, async fn() {
269	    guard @fs.kind(path, follow_symlink=false) == @fs.FileKind::Regular &&
270	      @fs.file_size(path) <= 65536L else {
271	      return Json::null()
272	    }
273	    @json.parse(@fs.read_file(path).text())
274	  }) catch {
275	    error =>
276	      if @async.is_being_cancelled() {
277	        raise error
278	      } else {
279	        Json::null()
280	      }
281	  }
282	  if field(previous, "priorLoss") is Some(Json::Array(losses)) {
283	    for loss in losses {
284	      if diagnostic_previous_losses.length() >= 31 {
285	        break
286	      }
287	      diagnostic_previous_losses.push(diagnostic_previous_loss(loss))
288	    }
289	    if losses.length() > 31 {
290	      diagnostic_previous_losses.push(diagnostic_previous_loss(Json::null()))
291	    }
292	  }
293	  diagnostic_previous_losses.push(diagnostic_previous_loss(previous))
294	  for event in diagnostic_previous_losses {
295	    diagnostic_pending.push({ event, failed: true, time: @env.now(), })
296	  }
297	  diagnostic_recording_health.incident = true
298	  diagnostic_recording_health.reason = "previous_run_unflushed"
299	  diagnostic_recording_health.phase = "recovery"
300	}
