419	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
420	  let length = if size > 262144L { 262144 } else { size.to_int() }
421	  let bytes = FixedArray::make(length, b'\x00')
422	  let read = file.read_at(bytes, position=size - length.to_int64())
423	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
424	  let lines = text.split("\n").to_array()
425	  let kept = FixedArray::make(lines.length(), false)
426	  let mut remaining = 65536
427	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
428	    if i == 0 && size > length.to_int64() {
429	      continue
430	    }
431	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
432	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
433	      100
434	    } else {
435	      0
436	    }
437	    let length = lines[i].length() + 1 + overhead
438	    if length <= remaining {
439	      kept[i] = true
440	      remaining -= length
441	    }
442	  }
443	  remaining = 65536
444	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
445	    if kept[i] || (i == 0 && size > length.to_int64()) {
446	      continue
447	    }
448	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
449	    let failed = field(event, "errorType") is Some(_) ||
450	      (match field(event, "status") {
451	        Some(Json::String(status)) =>
452	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
453	            status,
454	          )
455	        _ => false
456	      })
457	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
458	      100
459	    } else {
460	      0
461	    }
462	    let length = lines[i].length() + 1 + overhead
463	    if failed && length <= remaining {
464	      kept[i] = true
465	      remaining -= length
466	    }
467	  }
468	  let dropped_runs : Map[String, Bool] = Map([])
469	  for i in 0..<(lines.length() - 1) {
470	    if !kept[i] {
471	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
472	      if field(event, "runId") is Some(Json::String(id)) {
473	        dropped_runs.set(id, true)
474	      }
475	    }
476	  }
477	  let result = @buffer.Buffer(size_hint=131072)
478	  for i in 0..<lines.length() {
479	    if kept[i] {
480	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
481	      if field(event, "runId") is Some(Json::String(id)) {
482	        set_field(
483	          event,
484	          "runCompleteness",
485	          Json::string(
486	            if dropped_runs.contains(id) ||
487	              field(event, "runCompleteness") == Some(Json::string("partial")) {
488	              "partial"
489	            } else {
490	              "unknown"
491	            },
492	          ),
493	        )
494	        set_field(event, "runMissingReason", Json::string("retention_limit"))
495	        result.write_string_utf8(event.stringify() + "\n")
496	      } else {
497	        result.write_string_utf8(lines[i].to_owned() + "\n")
498	      }
499	    }
500	  }
501	  @utf8.decode_lossy(result.to_bytes())
502	}
