641	        ),
642	      )
643	    } else {
644	      evidence_truncated.val = true
645	    }
646	  }
647	  if evidence is Some(value) {
648	    if value.stringify().length() <= 65536 {
649	      set_field(
650	        event,
651	        "evidence",
652	        diagnostic_json(
653	          value,
