697	    set_field(event, "attempt", Json::number(value.to_double()))
698	  }
699	  if timeout_ms is Some(value) {
700	    set_field(event, "timeoutMs", Json::number(value.to_double()))
701	  }
702	  if retry_delay_ms is Some(value) {
703	    set_field(event, "retryDelayMs", Json::number(value.to_double()))
704	  }
705	  let failed = error_type is Some(_) ||
706	    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
707	      status,
708	    )
709	  if diagnostic_pending.length() >= 64 {
710	    let mut evict = -1
711	    if failed {
712	      for index in diagnostic_pending_inflight.val..<diagnostic_pending.length() {
713	        if !diagnostic_pending[index].failed {
714	          evict = index
715	          break
716	        }
717	      }
718	      if evict < 0 &&
719	        diagnostic_pending_inflight.val < diagnostic_pending.length() {
720	        evict = diagnostic_pending_inflight.val
721	      }
722	    }
723	    if evict < 0 {
724	      diagnostic_recording_failed("buffer_full", phase="buffer", event_time~)
725	      return
726	    }
727	    let removed = diagnostic_pending.remove(evict)
728	    diagnostic_pending.push({ event, failed, time: event_time, })
729	    diagnostic_recording_failed(
730	      "buffer_full",
731	      phase="buffer",
732	      event_time=removed.time,
733	    )
734	    try_flush_diagnostic_recording()
735	    return
736	  }
737	  diagnostic_pending.push({ event, failed, time: event_time, })
738	  try_flush_diagnostic_recording()
739	}
