1118	      while matched > 0 && value[matched] != value[index] {
1119	        matched = prefixes[matched - 1]
1120	      }
1121	      if value[matched] == value[index] {
1122	        matched += 1
1123	      }
1124	      prefixes[index] = matched
1125	    }
1126	    matched = 0
1127	    for index in 0..<boundary {
1128	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
1129	        matched = prefixes[matched - 1]
1130	      }
1131	      if matched < limit && value[matched] == chars[index] {
