346	///|
347	async fn Progress::message(
348	  self : Progress,
349	  text : String,
350	  debug~ : Bool,
351	  warning~ : Bool,
352	  emit~ : Bool = true,
353	) -> Unit {
354	  if self.protection_incomplete {
355	    self.details_truncated = true
356	    self.remember(
357	      "error detail unavailable because workspace protection values could not be read",
358	      warning=true,
359	    )
360	    return
361	  }
362	  for line in text.split("\n") {
363	    let text = line.trim().to_owned()
364	    if text == "" {
365	      continue
366	    }
367	    guard self.safe_message(text) is Some(safe) else {
368	      self.details_truncated = true
369	      continue
370	    }
371	    if !debug || warning {
372	      self.remember(safe, warning~)
373	    }
374	    if !emit {
375	      continue
376	    }
377	    if safe.has_prefix("#") {
378	      guard safe.split_once(" ") is Some((id, rest)) &&
379	        id.length() > 1 &&
380	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
381	        continue
382	      }
383	      let detail = rest.trim().to_owned()
384	      guard detail.has_prefix("[") ||
385	        detail.has_prefix("DONE") ||
386	        detail.has_prefix("ERROR") ||
387	        detail.has_prefix("CACHED") else {
388	        continue
389	      }
390	      if detail.has_prefix("ERROR") && debug && !warning {
391	        self.remember(safe, warning=true)
392	      }
393	      if self.builds.get(id.to_owned()) == Some(detail) {
394	        continue
395	      }
396	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
397	        self.builds.set(id.to_owned(), detail)
398	      }
399	      progress_message("Build " + id.to_owned() + ": " + detail)
400	    } else if classic_build_step(safe) {
401	      // Classic RUN output has no prefix. Only its own completion marker
402	      // ends this mode; phase events on another pipe can arrive ahead of it.
403	      self.classic_build = true
404	      progress_message("Build " + safe)
405	    } else if safe.has_prefix("Successfully built ") ||
406	      safe.has_prefix("Successfully tagged ") {
407	      self.classic_build = false
408	      progress_message("Build: " + safe)
409	    } else if self.classic_build && !warning {
410	      continue
411	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
412	      progress_message(self.stage + ": " + safe)
413	    } else if !debug && safe.has_prefix("[credential") {
414	      progress_message(self.stage + ": " + safe)
415	    }
416	  }
417	}
