109	///|
110	fn redact_credentials(text : String) -> String {
111	  let chars = text.iter().to_array()
112	  let buffer = @buffer.Buffer(size_hint=text.length())
113	  let mut i = 0
114	  let mut url = false
115	  while i < chars.length() {
116	    if credential_space(chars[i]) || ['"', '\''].contains(chars[i]) {
117	      url = false
118	    }
119	    if chars[i] == ':' &&
120	      i + 2 < chars.length() &&
121	      chars[i + 1] == '/' &&
122	      chars[i + 2] == '/' {
123	      url = true
124	      buffer.write_string_utf8("://")
125	      i += 3
126	      let mut end = i
127	      let mut user_end = None
128	      while end < chars.length() &&
129	            !credential_end(chars[end]) &&
130	            !['/', '?'].contains(chars[end]) {
131	        if chars[end] == '@' {
132	          user_end = Some(end)
133	        }
134	        end += 1
135	      }
136	      if user_end is Some(end) {
137	        buffer.write_string_utf8("[redacted]@")
138	        i = end + 1
139	      }
140	      continue
141	    }
142	    if url && ['?', '&'].contains(chars[i]) {
143	      let start = i
144	      i += 1
145	      while i < chars.length() && !credential_end(chars[i]) && chars[i] != '=' {
146	        i += 1
147	      }
148	      let name = credential_parameter(character_text(chars, start + 1, i))
149	      if i < chars.length() && chars[i] == '=' {
150	        i += 1
151	        buffer.write_string_utf8(character_text(chars, start, i))
152	        if credential_field(name) || ["key", "code"].contains(name.to_lower()) {
153	          if i + 10 <= chars.length() &&
154	            character_text(chars, i, i + 10) == "[redacted]" {
155	            i += 10
156	          }
157	          while i < chars.length() && !credential_end(chars[i]) {
158	            i += 1
159	          }
160	          buffer.write_string_utf8("[redacted]")
161	        }
162	      } else {
163	        buffer.write_string_utf8(character_text(chars, start, i))
164	      }
165	      continue
166	    }
167	    if credential_word(chars[i]) && (i == 0 || !credential_word(chars[i - 1])) {
168	      let start = i
169	      let mut end = i
170	      while end < chars.length() && credential_word(chars[end]) {
171	        end += 1
172	      }
173	      let word = character_text(chars, start, end)
174	      let lower = word.to_lower()
175	      if [
176	          "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "sk-", "age-secret-key-",
177	        ]
178	        .iter()
179	        .any(prefix => lower.has_prefix(prefix)) ||
180	        (word.has_prefix("eyJ") && end < chars.length() && chars[end] == '.') {
181	        while end < chars.length() && !credential_end(chars[end]) {
182	          end += 1
183	        }
184	        buffer.write_string_utf8("[redacted]")
185	        i = end
186	        continue
187	      }
188	      let mut separator = end
189	      if separator < chars.length() && ['"', '\''].contains(chars[separator]) {
190	        separator += 1
191	      }
192	      while separator < chars.length() && credential_space(chars[separator]) {
193	        separator += 1
194	      }
195	      if ["bearer", "basic"].contains(lower) &&
196	        separator > end &&
197	        separator < chars.length() {
198	        let mut value_end = separator
199	        if separator + 10 <= chars.length() &&
200	          character_text(chars, separator, separator + 10) == "[redacted]" {
201	          value_end = separator + 10
202	        }
203	        while value_end < chars.length() && !credential_end(chars[value_end]) {
204	          value_end += 1
205	        }
206	        let value = character_text(chars, separator, value_end).to_lower()
207	        if value_end > separator &&
208	          !["authentication", "auth", "token"].contains(value) {
209	          buffer.write_string_utf8(character_text(chars, start, separator))
210	          buffer.write_string_utf8("[redacted]")
211	          i = value_end
212	          continue
213	        }
214	      }
215	      let mut previous = start
216	      while previous > 0 && credential_space(chars[previous - 1]) {
217	        previous -= 1
218	      }
219	      let field_start = previous == 0 ||
220	        [';', ',', '{', '"', '\'', '?', '&'].contains(chars[previous - 1])
221	      let option = word.has_prefix("--")
222	      let prose_credential = (
223	          ["credential", "credentials"].contains(lower) && !field_start
224	        ) ||
225	        lower == "ssh_inject_git_credentials"
226	      let assignment = separator < chars.length() &&
227	        (
228	          chars[separator] == '=' ||
229	          (chars[separator] == ':' && !prose_credential)
230	        )
231	      if credential_field(word) && (assignment || (option && separator > end)) {
232	        let mut value = if assignment { separator + 1 } else { separator }
233	        while value < chars.length() && credential_space(chars[value]) {
234	          value += 1
235	        }
236	        buffer.write_string_utf8(character_text(chars, start, value))
237	        let quoted_key = start > 0 &&
238	          end < chars.length() &&
239	          ['"', '\''].contains(chars[start - 1]) &&
240	          chars[start - 1] == chars[end]
241	        if ["cookie", "set-cookie", "--cookie"].contains(lower) && !quoted_key {
242	          buffer.write_string_utf8("[redacted]")
243	          i = chars.length()
244	        } else if value + 10 <= chars.length() &&
245	          character_text(chars, value, value + 10) == "[redacted]" {
246	          buffer.write_string_utf8("[redacted]")
247	          i = value + 10
248	          while i < chars.length() && !credential_end(chars[i]) {
249	            i += 1
250	          }
251	        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
252	          let quote = chars[value]
253	          buffer.write_char_utf8(quote)
254	          value += 1
255	          while value < chars.length() && chars[value] != quote {
256	            if chars[value] == '\\' && value + 1 < chars.length() {
257	              value += 1
258	            }
259	            value += 1
260	          }
261	          buffer.write_string_utf8("[redacted]")
262	          i = value
263	        } else {
264	          let mut value_end = value
265	          while value_end < chars.length() && !credential_end(chars[value_end]) {
266	            value_end += 1
267	          }
268	          let scheme = character_text(chars, value, value_end).to_lower()
269	          if scheme == "bearer" || scheme == "basic" {
270	            while value_end < chars.length() &&
271	                  credential_space(chars[value_end]) {
272	              value_end += 1
273	            }
274	            buffer.write_string_utf8(character_text(chars, value, value_end))
275	            value = value_end
276	            while value_end < chars.length() &&
277	                  !credential_end(chars[value_end]) {
278	              value_end += 1
279	            }
280	          }
281	          if value + 10 <= chars.length() &&
282	            character_text(chars, value, value + 10) == "[redacted]" {
283	            value_end = value + 10
284	          }
285	          if value_end > value {
286	            buffer.write_string_utf8("[redacted]")
287	          }
288	          i = value_end
289	        }
290	        continue
291	      }
292	      buffer.write_string_utf8(word)
293	      i = end
294	      continue
295	    }
296	    buffer.write_char_utf8(chars[i])
297	    i += 1
298	  }
299	  @utf8.decode_lossy(buffer.to_bytes())
300	}
