302	///|
303	fn Progress::safe_message(self : Progress, text : String) -> String? {
304	  guard terminal_text(text) is Some(text) else { return None }
305	  let lower = text.to_lower()
306	  if lower.contains("-----begin ") && lower.contains("private key-----") {
307	    self.private_key = REDACTED ")
308	    return Some("[private key redacted]")
309	  }
310	  if self.private_key {
311	    if lower.contains("-----end ") && lower.contains("private key-----") {
312	      self.private_key = false
313	    }
314	    return None
315	  }
316	  let known = redact_known_values(text, self.secrets)
317	  let mut safe = redact_known_values(redact_credentials(known), self.secrets)
318	  if safe.length() > 1024 {
319	    safe = safe[:1024].to_owned() + "… [truncated]"
320	    self.details_truncated = true
321	  }
322	  Some(safe)
323	}
