   198	async fn invoke(
   199	  mode : String,
   200	  env : Map[String, String],
   201	  directory : String,
   202	  payload? : Json,
   203	) -> (Int32, String, String) {
   204	  if mode == "create" &&
   205	    @fs.exists(directory + "/orca.yaml") &&
   206	    @fs.read_file(directory + "/orca.yaml").text().contains("orca-server") {
   207	    settings_fixture(directory, env)
   208	  }
   209	  let executable = integration_binary()
   210	  let input = if payload is Some(value) {
   211	    @fs.write_file(directory + "/stdin.json", value.stringify())
   212	    Some(@process.redirect_from_file(directory + "/stdin.json"))
   213	  } else {
   214	    None
   215	  }
   216	  let (status, stdout, stderr) = @process.collect_output(
   217	    executable,
   218	    if (mode == "recover" || mode == "restart") && payload is None {
   219	      [mode]
   220	    } else {
   221	      ["recipe", mode]
   222	    },
   223	    extra_env=env,
   224	    stdin?=input,
   225	  )
   226	  let diagnostics = if status != 0 { fixture_process_errors(env) } else { "" }
   227	  (status, stdout.text(), stderr.text() + diagnostics)
   228	}
