   230	///|
   231	async fn fixture_process_errors(env : Map[String, String]) -> String {
   232	  let diagnostics = []
   233	  try {
   234	    let path = env.get("XDG_STATE_HOME").unwrap() +
   235	      "/orca-env-devsy/events.jsonl"
   236	    for line in @fs.read_file(path).text().split("\n") {
   237	      if line == "" {
   238	        continue
   239	      }
   240	      let event = @json.parse(line.to_owned())
   241	      if field(event, "status") != Some(Json::string("process-error")) {
   242	        continue
   243	      }
   244	      let safe = Json::empty_object()
   245	      for name in ["process_os", "process_utf8", "process_api"] {
   246	        if field(event, "errorType") == Some(Json::string(name)) {
   247	          set_field(safe, "errorType", Json::string(name))
   248	        }
   249	      }
   250	      for name in ["read"] {
   251	        if field(event, "phase") == Some(Json::string(name)) {
   252	          set_field(safe, "phase", Json::string(name))
   253	        }
   254	      }
   255	      if field(event, "osErrno") is Some(Json::Number(code, ..)) &&
   256	        code > 0 &&
   257	        code < 4096 &&
   258	        code == code.to_int().to_double() {
   259	        set_field(safe, "osErrno", Json::number(code))
   260	      }
   261	      diagnostics.push(safe.stringify())
   262	    }
   263	  } catch {
   264	    _ => ()
   265	  }
   266	  diagnostics.join("\n")
   267	}
