  2	async fn read_registration(socket : @socket.Tcp, limit : Int32) -> Json {
  3	  let header = @buffer.Buffer()
  4	  while true {
  5	    let byte = socket.read_exactly(1)
  6	    if byte == b"\n" {
  7	      break
  8	    }
  9	    guard header.length() < 8 else {
 10	      raise AdapterError("Invalid registration length")
 11	    }
 12	    header.write_bytes(byte)
 13	  }
 14	  let length = @string.parse_int(@utf8.decode(header.to_bytes()))
 15	  guard length > 0 && length <= limit else {
 16	    raise AdapterError("Registration is too large")
 17	  }
 18	  @json.parse(@utf8.decode(socket.read_exactly(length))) catch {
 19	    _ => raise AdapterError("Invalid registration JSON")
 20	  }
 21	}
