104	async fn accept_registration(
105	  socket : @socket.Tcp,
106	  root : String,
107	  environments : Map[String, Map[String, String]],
108	  identity : Json,
109	) -> Unit {
110	  defer socket.close()
111	  @async.with_timeout(10000, async fn() {
112	    write_registration(socket, identity)
113	    let request = read_registration(socket, 4194304)
114	    let directory = @fs.realpath(required(request, "directory"))
115	    guard directory.has_prefix(@fs.realpath(root) + "/tunnels/") &&
116	      @fs.exists(directory + "/state.json") else {
117	      raise AdapterError(
118	        "Workspace registration is outside the state directory",
119	      )
120	    }
121	    guard field(request, "environment") is Some(Json::Object(values)) else {
122	      raise AdapterError("Missing workspace execution environment")
123	    }
124	    let environment : Map[String, String] = Map([])
125	    for (name, value) in values {
126	      guard value is Json::String(value) else {
127	        raise AdapterError("Invalid workspace execution environment")
128	      }
129	      environment.set(name, value)
130	    }
131	    let lock = @fs.open(
132	      directory + "/environment.lock",
133	      mode=ReadWrite,
134	      create_mode=OpenOrCreate,
135	      permission=0o600,
136	    )
137	    defer lock.close()
138	    while !lock.try_lock(Exclusive) {
139	      @async.sleep(10)
140	    }
141	    let temporary = directory + "/environment.json.tmp"
142	    if @fs.exists(temporary) {
143	      @fs.remove(temporary)
144	    }
145	    defer (@fs.remove(temporary) catch { _ => () })
146	    @fs.write_file(
147	      temporary,
148	      field(request, "environment").unwrap().stringify(),
149	      create_mode=CreateNew,
150	      permission=0o600,
151	    )
152	    @fs.rename(temporary, directory + "/environment.json", replace=true)
153	    environments.set(directory, environment)
154	    if environment.get("ORCA_ENV_DEVSY_RECORDING") != Some("0") {
155	      save_diagnostic(
156	        "supervisor-registration",
157	        "success",
158	        tunnel_directory=directory,
159	        recording=true,
160	      )
161	    }
162	    write_registration(socket, {
163	      "accepted": true,
164	      "diagnosticHealth": diagnostic_health_snapshot(),
