306	async fn workspace_program(state : Json, program : String) -> String {
307	  let cwd = workspace_directory(state).unwrap_or(
308	    @env.current_dir().unwrap_or("/"),
309	  )
310	  if program.has_prefix("/") {
311	    return program
312	  }
313	  if program.contains("/") {
314	    return cwd + "/" + program
315	  }
316	  let path = field(field(state, "devsyEnv").unwrap_or(Json::null()), "PATH")
317	  let path = match path {
318	    Some(Json::String(value)) => value
319	    _ => "/usr/bin:/bin"
320	  }
321	  let mut fallback = None
322	  for directory in path.split(":") {
323	    let directory = if directory.has_prefix("/") {
324	      directory.to_owned()
325	    } else {
326	      cwd + "/" + directory.to_owned()
327	    }
328	    let candidate = directory + "/" + program
329	    if fallback is None {
330	      fallback = Some(candidate)
331	    }
332	    if transport_access(@utf8.encode(candidate + "\u0000"), 1) == 0 &&
333	      @fs.kind(candidate) != @fs.FileKind::Directory {
334	      return candidate
335	    }
336	  }
337	  fallback.unwrap_or(cwd + "/" + program)
338	}
